code='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objs = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft(); cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx)); q.append((ny,nx))
            r0=min(y for y,x in cells); r1=max(y for y,x in cells)
            c0=min(x for y,x in cells); c1=max(x for y,x in cells)
            objs.append((c0, r0, color, r1-r0+1, c1-c0+1))
    objs.sort()
    out=[[0]*w for _ in range(h)]
    top=left=0
    for i,(_,r0,color,oh,ow) in enumerate(objs):
        if i:
            ph,pw=objs[i-1][3],objs[i-1][4]
            top += ph-1; left += pw-1
        for y in range(oh):
            for x in range(ow):
                if top+y < h and left+x < w:
                    out[top+y][left+x]=color
    return out
'''
